from common import *

def room():
    c1 = calc('c1', "GaAs: gap, cyclotron resonance, intrinsic carriers", 'normal',
      "Ensslin, HS20 task 4. In GaAs (direct gap) the absorption edge in the 300 K spectrum rises at $\\nu=344$ THz. Effective masses $m_e^*=0.067\\,m_e$ and $m_h^*=0.45\\,m_e$. Use $k_BT=25$ meV for the Boltzmann factor (as in the key) and $T=300$ K in the carrier-density formula. Mobilities $\\mu_e=1.6$ and $\\mu_h=0.4$ m$^2$/(V s).",
      V('h', 'e', 'kB', 'c', nu=344e12, kT=0.025, T=300.0, lam=671e-9, me_=0.067, mh_=0.45, mue=1.6, muh=0.4),
      [step('Eg', "Band gap $E_g=h\\nu$ in eV.", "h*nu/e", "eV", ["eV", "meV", "THz", "nm"], 0.01,
            "$h=4.136$ meV/THz, so 344 THz = 1.42 eV. The key also accepts 1.435 eV: the first rise is the exciton just below the edge."),
       step('p', "Boltzmann factor for exciting an electron across the gap, $\\exp(-E_g/k_BT)$.", "exp(-Eg/kT)", "dimensionless", ["dimensionless", "eV", "K", "m^-3"], 0.15,
            "$e^{-1.42/0.025}=2\\times10^{-25}$: the gap is $55\\,k_BT$. Compare: Si ($E_g=1.1$ eV) is not many orders better. (Key: $2\\times10^{-25}$.)", tolType='log'),
       step('Be', "Cyclotron resonance: field $B=2\\pi c\\,m^*/(e\\lambda)$ so that $\\omega_c=eB/m^*$ matches the laser line $\\lambda=671$ nm, for electrons, in T.", "2*pi*c*me_*me/(e*lam)", "T", ["T", "kT", "mT", "A/m"], 0.03,
            "$\\omega_c=eB/m^*=2\\pi c/\\lambda$. The result $\\approx1.1$ kT is far beyond a 10 T magnet (key). Cyclotron resonance is run at microwave/far-IR frequencies instead (script 5.1.3)."),
       step('Bh', "Same for holes ($m^*=0.45m_e$), in kT.", "2*pi*c*mh_*me/(e*lam)/1e3", "kT", ["kT", "T", "mT", "A/m"], 0.03,
            "Seven times higher: $B\\propto m^*$."),
       step('ni', "Intrinsic carrier density $n_i=p_i=2\\big(\\frac{k_BT}{2\\pi\\hbar^2}\\big)^{3/2}(m_e^*m_h^*)^{3/4}e^{-E_g/2k_BT}$ in m$^{-3}$ (use $E_g$ from step 1, $T=300$ K).",
            "2*(kB*T/(2*pi*hbar**2))**1.5*(me_*mh_*me*me)**0.75*exp(-Eg*eV/(2*kB*T))", "m^-3", ["m^-3", "cm^-3", "m^-2", "J m^-3"], 0.1,
            "Mass-action law $n_ep_h=n_e^{\\rm eff}n_h^{\\rm eff}e^{-E_g/k_BT}$ (script 5.16). Key: $2.15\\times10^{12}$ m$^{-3}$ for 1.42 eV, $1.6\\times10^{12}$ for 1.435 eV: GaAs is an almost perfect insulator at room temperature when undoped."),
       step('mu', "Position of the Fermi level above mid-gap, $\\frac34k_BT\\ln(m_h^*/m_e^*)$ in meV.", "0.75*kB*T*log(mh_/me_)/eV*1e3", "meV", ["meV", "eV", "K", "kT"], 0.03,
            "Script eq. 5.14: $\\epsilon_F=\\frac{\\epsilon_v+\\epsilon_c}2+\\frac34k_BT\\ln(m_h^*/m_e^*)$. Heavier holes mean more valence states, so the Fermi level moves up towards the conduction band. Key: 36.9 meV."),
       step('sig', "Conductivity $\\sigma=n_ie(\\mu_e+\\mu_h)$ in S/m.", "ni*e*(mue+muh)", "S/m", ["S/m", "S m", "Ohm m", "m^2/(V s)"], 0.12,
            "Key: $689$ nS/m (1.42 eV) or $516$ nS/m (1.435 eV). Electrons carry 80 % of the current ($\\mu_e=4\\mu_h$).")],
      80)

    c2 = calc('c2', "A hydrogen atom in a crystal: the donor", 'normal',
      "HS20 task 4(f). GaAs doped with donors, $N_d=10\\times10^{22}$ m$^{-3}$, $\\epsilon_r=12.9$, $m_e^*=0.067\\,m_e$, lattice constant $a=565$ pm. The extra electron orbits the positive donor ion like in hydrogen, but with $m_e\\to m_e^*$ and $\\epsilon_0\\to\\epsilon_r\\epsilon_0$ (script 5.3.1). Hydrogen: Rydberg $13.606$ eV, Bohr radius $0.529$ Å.",
      V('kB', 'Ry', 'a0', ms=0.067, er=12.9, Nd=1.0e23, alat=5.65e-10),
      [step('Ed', "Donor binding energy $E_d=\\mathrm{Ry}\\,\\frac{m^*/m_e}{\\epsilon_r^2}$ in meV.", "Ry*ms/er**2*1e3", "meV", ["meV", "eV", "K", "um"], 0.02,
            "Hydrogen energies scale with $m^*/\\epsilon_r^2$: $13.6\\,{\\rm eV}\\times0.067/166=5.5$ meV. Key: 5.5 meV."),
       step('rd', "Donor Bohr radius $r_d=a_0\\,\\epsilon_r\\,m_e/m^*$ in nm.", "a0*er/ms*1e9", "nm", ["nm", "A", "um", "m"], 0.02,
            "Hydrogen radii scale with $\\epsilon_r/(m^*/m_e)$: $0.0529\\,{\\rm nm}\\times193=10.2$ nm (key)."),
       step('ratio', "Radius in lattice constants $r_d/a$.", "rd*1e-9/alat", "dimensionless", ["dimensionless", "nm", "meV", "m^-3"], 0.03,
            "$\\approx18$: the electron orbit spans thousands of host atoms, which therefore act as a continuous polarisable medium. That justifies using the **host's** $\\epsilon_r$ (key), not the donor's."),
       step('sp', "Mean donor spacing $N_d^{-1/3}$ in nm.", "Nd**(-1/3)*1e9", "nm", ["nm", "um", "A", "m"], 0.02,
            "$(10^{23})^{-1/3}$ m = 21.5 nm, about $2r_d$: the donor orbits just touch. At this concentration the donor states overlap and an impurity band forms (script remark after 5.21)."),
       step('Tf', "Freeze-out temperature scale $E_d/k_B$ in K.", "Ed*1e-3*eV/kB", "K", ["K", "meV", "eV", "mK"], 0.03,
            "Below $\\sim E_d/k_B\\approx64$ K the electrons freeze back onto donors ($n_e\\propto e^{-E_d/2k_BT}$, script 5.27); between roughly 100 K and room temperature all donors are ionised (exhaustion) and $n_e=N_d$ flat.")],
      70)

    c3 = calc('c3', "The 1D semiconductor with cosine bands", 'normal',
      "Zheludev, Jan 2024, Problem 3 (script 5.2), with numbers. Valence band $E_{vb}=2t_{vb}[\\cos(ka)-1]$, conduction band $E_{cb}=E_G-2t_{cb}[\\cos(ka)-1]$ with $t_{cb}=2t_{vb}=t$, so $t_{vb}=t/2$. Both extrema are at $k=0$ (direct gap). Take $t=0.50$ eV, $a=4.0$ Å, $E_G=0.30$ eV, $T=300$ K and $\\mu$ at mid-gap, $k_BT\\ll\\mu,E_G-\\mu$ (Boltzmann limit). 1D density of states per length (both $\\pm k$ points and the spin factor 2 included): $\\nu_{cb}=1/[\\pi a\\sqrt{t_{cb}(E-E_G)}]$, $\\nu_{vb}=1/[\\pi a\\sqrt{t_{vb}(-E)}]$.",
      V('kB', t=0.5, a=4.0e-10, EG=0.30, T=300.0),
      [step('mcb', "Electron effective mass $m_{cb}^*=\\hbar^2/(2t_{cb}a^2)$ in units of $m_e$.", "hbar**2/(2*t*eV*a**2)/me", "dimensionless", ["dimensionless", "kg", "eV", "A^-1"], 0.02,
            "Expand: $E_{cb}\\approx E_G+t_{cb}a^2k^2$, so $\\partial^2E/\\partial k^2=2t_{cb}a^2$ and $m^*=\\hbar^2/(2t_{cb}a^2)$. Here $3.81/(0.5\\times16)=0.48$."),
       step('mvb', "Hole effective mass $m_h^*=\\hbar^2/(2t_{vb}a^2)$ in $m_e$ ($t_{vb}=t/2$).", "hbar**2/(2*(t/2)*eV*a**2)/me", "dimensionless", ["dimensionless", "kg", "eV", "A^-1"], 0.02,
            "$E_{vb}\\approx-t_{vb}a^2k^2$ (negative curvature) gives a positive hole mass $m_h^*=-\\hbar^2/(\\partial^2E/\\partial k^2)=\\hbar^2/(2t_{vb}a^2)$. The flatter band is the heavier one: $m_h^*/m_e^*=2$."),
       step('ne', "Electron density per length at $\\mu=E_G/2$: $n_e=\\frac{\\sqrt{k_BT}}{a\\sqrt{\\pi t_{cb}}}\\,e^{(\\mu-E_G)/k_BT}$ in m$^{-1}$.", "sqrt(kB*T/(pi*t*eV))/a*exp(-(EG/2)*eV/(kB*T))", "m^-1", ["m^-1", "m^-3", "m^-2", "m"], 0.03,
            "Use $f\\approx e^{(\\mu-E)/k_BT}$ and $\\int_0^\\infty x^{-1/2}e^{-x}dx=\\sqrt\\pi$. Divide by $a$ for density per length. Note the unusual 1D power: $n\\propto\\sqrt T$ (3D: $T^{3/2}$)."),
       step('nh', "Hole density per length at $\\mu=E_G/2$, $n_h=\\frac{\\sqrt{k_BT}}{a\\sqrt{\\pi t_{vb}}}\\,e^{-\\mu/k_BT}$ in m$^{-1}$.", "sqrt(kB*T/(pi*(t/2)*eV))/a*exp(-(EG/2)*eV/(kB*T))", "m^-1", ["m^-1", "m^-3", "m^-2", "m"], 0.03,
            "Same integral with the lighter hopping $t_{vb}=t/2$: $n_h/n_e=\\sqrt{t_{cb}/t_{vb}}=\\sqrt2$ at mid-gap."),
       step('dmu', "Intrinsic chemical potential: $n_e=n_h$ gives $e^{(2\\mu-E_G)/k_BT}=\\sqrt{t_{cb}/t_{vb}}$. Shift $\\mu-E_G/2$ in meV.", "kB*T/eV*log(2)/4*1e3", "meV", ["meV", "eV", "K", "kT"], 0.03,
            "$\\mu=\\frac{E_G}2+\\frac{k_BT}{4}\\ln2=E_G/2+4.5$ meV. (The printed Jan-2024 key states $\\frac{k_BT}2\\ln2$. Solving $e^{(2\\mu-E_G)/k_BT}=\\sqrt2$ gives $\\frac14$, and the content check confirms it by numerical integration of the Fermi–Dirac occupation. Cross-check with 3D, script 5.14: $\\frac34k_BT\\ln(m_h^*/m_e^*)$ from $n\\propto m^{3/2}$; in 1D $n\\propto m^{1/2}$ gives $\\frac14k_BT\\ln(m_h^*/m_e^*)$.)")],
      70)

    c4 = calc('c4', "The p-n junction: how wide is the depletion layer?", 'normal',
      "Script 5.4. Silicon p–n junction at 300 K: acceptors $N_a=10^{16}$ cm$^{-3}$, donors $N_d=10^{17}$ cm$^{-3}$, $E_g=1.12$ eV, density-of-states masses $m_e^*=1.08\\,m_e$, $m_h^*=0.56\\,m_e$, $\\epsilon_r=11.7$. The contact potential is $eV=\\Delta+k_BT\\ln\\frac{N_dN_a}{n_e^{\\rm eff}n_h^{\\rm eff}}$ (eq. 5.36) and the total depletion width $d_n+d_p=\\sqrt{\\frac{2\\epsilon\\epsilon_0V}{e}\\,\\frac{N_a+N_d}{N_aN_d}}$ (eq. 5.46).",
      V('kB', 'e', 'eps0', Na=1.0e22, Nd=1.0e23, er=11.7, Eg=1.12, T=300.0, mc=1.08, mv=0.56, U=0.3),
      [step('Nc', "Effective density of states of the conduction band $n_e^{\\rm eff}=2(m_e^*k_BT/2\\pi\\hbar^2)^{3/2}$ in m$^{-3}$.", "2*(mc*me*kB*T/(2*pi*hbar**2))**1.5", "m^-3", ["m^-3", "cm^-3", "m^-2", "J m^-3"], 0.03,
            "Eq. 5.11. $\\approx2.8\\times10^{19}$ cm$^{-3}$ for Si."),
       step('Nv', "Same for the valence band ($m_h^*=0.56\\,m_e$) in m$^{-3}$.", "2*(mv*me*kB*T/(2*pi*hbar**2))**1.5", "m^-3", ["m^-3", "cm^-3", "m^-2", "J m^-3"], 0.03,
            "$\\approx1.0\\times10^{19}$ cm$^{-3}$."),
       step('V0', "Contact potential $V$ in volts.", "Eg+kB*T/e*log(Nd*Na/(Nc*Nv))", "V", ["V", "mV", "eV/K", "V/m"], 0.02,
            "The log is negative here ($N_aN_d\\ll n^{\\rm eff}n^{\\rm eff}$) and small compared with $\\Delta$: $eV\\approx E_g-0.33$ eV $\\approx0.80$ eV. (Script 5.37: $eV\\sim\\Delta$.)"),
       step('d', "Total depletion width $d_n+d_p$ in micrometres.", "sqrt(2*er*eps0*V0/e*(Na+Nd)/(Na*Nd))*1e6", "um", ["um", "nm", "mm", "A"], 0.03,
            "$d_n=\\sqrt{\\frac{2\\epsilon\\epsilon_0V}{e}\\frac{N_a}{N_d(N_d+N_a)}}$, $d_p=\\sqrt{\\frac{2\\epsilon\\epsilon_0V}{e}\\frac{N_d}{N_a(N_a+N_d)}}$ from Poisson's equation with $N_dd_n=N_ad_p$. About $0.3\\,\\mu$m. Script quotes $10^2$–$10^4$ Å."),
       step('dpdn', "How much wider is the depletion layer on the p side, $d_p/d_n$?", "Nd/Na", "dimensionless", ["dimensionless", "um", "V", "eV"], 0.02,
            "Charge neutrality $N_dd_n=N_ad_p$: the lightly doped side is depleted more deeply."),
       step('fwd', "Forward bias $U=0.3$ V: new width as a fraction of the zero-bias width, $\\sqrt{1-U/V}$.", "sqrt(1-U/V0)", "dimensionless", ["dimensionless", "V", "um", "eV"], 0.03,
            "Eq. 5.48: $d(U)=d(0)\\sqrt{1-U/V}$. Forward bias narrows the layer and lowers the barrier $V-U$, so the recombination current $\\propto e^{-e(V-U)/k_BT}$ rises exponentially; reverse bias does the opposite (rectification).")],
      80)

    c5 = calc('c5', "The LED forge: gap to colour", 'fermi',
      "Quick fight. A light-emitting diode emits photons of energy $\\approx E_g$ when electrons and holes recombine across the gap (script 5.1): $\\lambda[{\\rm nm}]=1239.84/E_g[{\\rm eV}]$. Wien's law $\\lambda_{\\max}T=b=2.898\\times10^{-3}$ m K connects colour to temperature in astrophysics. (A blue InGaN LED has $E_g\\approx2.70$ eV.)",
      V('h', 'c', 'e', b=2.897771955e-3, EgLED=2.70, EgGaAs=1.42, TSun=5772.0),
      [step('lam', "Wavelength of the blue LED in nm.", "h*c/(EgLED*e)*1e9", "nm", ["nm", "um", "eV", "THz"], 0.02,
            "$E=hc/\\lambda$: $\\lambda=459$ nm."),
       step('lamGaAs', "Wavelength emitted by GaAs ($E_g=1.42$ eV) in nm: is it visible?", "h*c/(EgGaAs*e)*1e9", "nm", ["nm", "um", "eV", "THz"], 0.02,
            "874 nm: near infrared, invisible. GaAs lasers/LEDs are used in remote controls and fibre links; visible LEDs need wider gaps (GaP, GaN, InGaN)."),
       step('TW', "A blackbody whose Wien peak sits at the LED wavelength has temperature $b/\\lambda$ in K.", "b/(lam*1e-9)", "K", ["K", "eV", "nm", "J"], 0.03,
            "$\\approx6300$ K: a hot F-type star is as blue-white as this peak, but its spectrum is a broad blackbody, the LED's is a narrow line of width $\\sim k_BT$ (efficiency!)."),
       step('EgSun', "Gap whose photons match the Sun's Wien peak ($T_\\odot=5772$ K) in eV.", "h*c/(b/TSun)/e", "eV", ["eV", "meV", "K", "nm"], 0.03,
            "The Sun peaks at $b/T=502$ nm (matches the astro room *Light Deck*: 502 nm), i.e. $E=2.47$ eV. Photovoltaics balance two losses: gap too large wastes the red/IR light, too small wastes the excess energy as heat (Shockley–Queisser optimum $\\sim1.3$ eV).")],
      30)

    SRC = dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 3 '1D Semiconductors' (Zheludev, 16 Aug 2024); solution: solutions/Einführung in die Festkörperphysik HS23 (Solution).pdf, Problem 3")
    boss1 = boss('b1', "Boss: an indirect 1D semiconductor (exam problem)", SRC, 30,
      "Solve on paper under the timer, then enter the numbers for the game parameters. Parts (a), (b), (c), (d) and (e) are self-graded.",
      ["Suppose we have a 1D semiconductor with a conduction band $E_{cb}=E_G+2t_{cb}[\\cos(ka)+1]$ and a valence band $E_{vb}=2t_{vb}[\\cos(ka)-1]$, where $t_{cb}=\\frac12t_{vb}=t$. The chemical potential satisfies $0<\\mu<E_G$.",
       "(a) [0.5 pt] Sketch the band structure to scale, with labels.  (b) [0.25 pt] Direct or indirect gap?",
       "(c) [0.5 pt] Assume the Fermi level is far from both bands: $|E_G-\\mu|\\gg k_BT$ and $\\mu\\gg k_BT$. Write the dispersions near the extrema to second order.",
       "(d) [0.5 pt] Effective masses of electrons and holes.  (e) [0.5 pt] Density of states per unit length of both bands.",
       "(f) [0.5 pt] Electron density per length in the conduction band and hole density in the valence band.",
       "(g) [0.25 pt] The conductivities of holes and electrons at high temperature are equal, $\\sigma_e=\\sigma_h$. What is the ratio of the relaxation times $\\tau_e/\\tau_h$?",
       "Game numbers: $t=0.40$ eV (so $t_{vb}=0.80$ eV), $a=5.0$ Å, $E_G=0.50$ eV, $T=300$ K, $\\mu=E_G/2$ for (f) and (g)."],
      [fa('mcb', "(d) $m_e^*/m_e$ of the conduction band ($t_{cb}=t$).", "hbar**2/(2*t*eV*a**2)/me", dict(t=0.4, a=5.0e-10), 0.02),
       fa('mvb', "(d) $m_h^*/m_e$ of the valence band ($t_{vb}=2t$).", "hbar**2/(2*2*t*eV*a**2)/me", dict(t=0.4, a=5.0e-10), 0.02),
       fa('ne', "(f) $n_e$ per length at $\\mu=E_G/2$ in m$^{-1}$.", "sqrt(kB*T/(pi*t*eV))/a*exp(-(EG/2)*eV/(kB*T))", dict(kB=K['kB'], t=0.4, a=5.0e-10, EG=0.5, T=300.0), 0.03),
       fa('nh', "(f) $n_h$ per length at $\\mu=E_G/2$ in m$^{-1}$.", "sqrt(kB*T/(pi*2*t*eV))/a*exp(-(EG/2)*eV/(kB*T))", dict(kB=K['kB'], t=0.4, a=5.0e-10, EG=0.5, T=300.0), 0.03),
       fa('tau', "(g) $\\tau_e/\\tau_h=\\dfrac{m_e^*}{m_h^*}\\dfrac{n_h}{n_e}$ at $\\mu=E_G/2$.", "sqrt(2)", dict(), 0.01)],
      ["(a),(b) $E_{vb}$ has its maximum 0 at $k=0$; $E_{cb}$ has its minimum $E_G$ at $k=\\pm\\pi/a$ and its maximum $E_G+4t_{cb}$ at $k=0$: **indirect** gap (valence-band maximum and conduction-band minimum at different $k$). Draw with scales $4t_{cb}=4t$ and $4t_{vb}=8t$, zone edges $\\pm\\pi/a$.",
       "(c) $E_{cb}\\approx E_G+t\\,a^2(k-\\pi/a)^2$, $E_{vb}\\approx-2t\\,a^2k^2$.",
       "(d) $m^*=\\hbar^2(\\partial^2E/\\partial k^2)^{-1}$: $m_{cb}^*=\\hbar^2/(2ta^2)$ and $m_{vb}^*=\\hbar^2/(4ta^2)$. The holes are lighter here ($m_e^*/m_h^*=2$).",
       "(e) $\\nu(E)=\\frac{2\\cdot2}{2\\pi}\\frac{dk}{dE}$ (factor 2 for the two points $\\pm k$ at each energy, factor 2 for spin): $\\nu_{cb}=\\frac{1}{\\pi a\\sqrt{t(E-E_G)}}$ for $E\\ge E_G$, $\\nu_{vb}=\\frac1{\\pi a\\sqrt{2t(-E)}}$ for $E\\le0$.",
       "(f) With $f\\approx e^{(\\mu-E)/k_BT}$ and $\\int_0^\\infty x^{-1/2}e^{-x}dx=\\sqrt\\pi$: $n_e=\\frac1a\\sqrt{\\frac{k_BT}{\\pi t_{cb}}}\\,e^{(\\mu-E_G)/k_BT}$ and, with $t_{vb}=2t$, $n_h=\\frac1a\\sqrt{\\frac{k_BT}{2\\pi t}}\\,e^{-\\mu/k_BT}$.",
       "(g) $\\sigma=ne^2\\tau/m^*$. $\\sigma_e=\\sigma_h$ gives $\\frac{\\tau_e}{\\tau_h}=\\frac{m_e^*}{m_h^*}\\frac{n_h}{n_e}=2\\cdot\\frac1{\\sqrt2}e^{(E_G-2\\mu)/k_BT}=\\sqrt2\\,e^{(E_G-2\\mu)/k_BT}$, which is $\\sqrt2$ at mid-gap.",
       "Remark (Jan 2024 variant, direct gap): the intrinsic $\\mu$ is $E_G/2+\\frac{k_BT}4\\ln\\frac{t_{cb}}{t_{vb}}$ (script-consistent; the key prints a factor 2 more)."],
      90)

    return dict(file='semiconductor-forge', id='ss-semiconductor-forge', region="Solid State Crystal Caverns", title="The Semiconductor Forge", course="solid-state",
      topics=["band gap, direct/indirect", "effective mass, cyclotron resonance", "intrinsic carriers, mass-action law", "donors and acceptors, hydrogenic model", "p-n junction, depletion layer", "LED colour and photovoltaics"],
      sources=[dict(file="materials/solid-state/old-exams/HS23.pdf", where="Problem 3 (Zheludev, Jan 2024); solution (1), Problem 3"),
               dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 3 (Aug 2024); solution: HS23 (Solution).pdf, Problem 3"),
               dict(file="materials/solid-state/old-exams/HS20.pdf", where="Task 4 GaAs (12 pt), MC (a) carrier density, (c) p-type E_F, (o) 2D DOS, (t) p-n junction band diagram; solution HS20"),
               dict(file="materials/solid-state/scripts/Script-2026_2026-09-01.pdf", where="Ch. 5.1-5.4 (pp. 113–135): gap, effective mass, cyclotron resonance, intrinsic carriers, doping, p-n junction"),
               dict(file="notes/solid-state/04-semiconductors-and-magnetism.md", where="transcription, formulas and checks")],
      links=[dict(course="qm", room="hydrogen-lamp", why="Donors are hydrogen atoms with $m\\to m^*$, $\\epsilon_0\\to\\epsilon_r\\epsilon_0$: energies scale as $m^*/\\epsilon_r^2$, radii as $\\epsilon_r/m^*$."),
             dict(course="astro", room="photometry-radiation", why="LED colour, band-gap absorption edges and Wien's law: the gap sets which photons a detector or solar cell can use.")],
      intro="At the forge the band gap decides everything. Thermally excited carriers, doping with hydrogen-like donors, the depletion layer of a p-n junction and the colour of a light-emitting diode all follow from one parabola near each band edge.",
      encounters=[c1, c2, c3, c4, c5, boss1])
